function statementSMS(personId){const person=db.people.find(p=>p.id===personId);if(!person)throw Error('ব্যক্তির তথ্য পাওয়া যায়নি।');const bangla=typeof uiLanguage!=='undefined'&&uiLanguage==='bn',entries=db.entries.filter(e=>e.person===personId).slice().sort((a,b)=>(b.date+' '+(b.time||'00:00')).localeCompare(a.date+' '+(a.time||'00:00'))),last=entries[0],net=netBalance(person),amount=money(Math.abs(net)),owner=db.profile?.name||'DailyTally',lines=bangla?['প্রিয় '+person.name+',','আপনার লেনদেনের সংক্ষিপ্ত হিসাব:']:['Hello '+person.name+',','Here is your transaction summary:'];
 if(last){const kind=bangla?({given:'আপনাকে দেওয়া হয়েছে',received:'আপনার কাছ থেকে পাওয়া গেছে',due:'বাকি যোগ হয়েছে',settle:'পরিশোধ রেকর্ড হয়েছে'}[last.kind]||'সর্বশেষ লেনদেন'):({given:'Paid to you',received:'Received from you',due:'Credit recorded',settle:'Payment recorded'}[last.kind]||'Last transaction');lines.push(kind+': '+money(last.amount));const date=new Intl.DateTimeFormat(bangla?'bn-BD':'en-GB',{day:'numeric',month:'short',year:'numeric'}).format(new Date(last.date+'T12:00:00Z'));let time=last.time&&typeof displayTime12==='function'?displayTime12(last.time):'';if(bangla)time=time.replace(/\d/g,d=>'০১২৩৪৫৬৭৮৯'[Number(d)]).replace('AM','এএম').replace('PM','পিএম');lines.push((bangla?'তারিখ: ':'Date: ')+date+(time?' · '+time:''));if(last.note)lines.push((bangla?'বিবরণ: ':'Note: ')+last.note.slice(0,160))}
 lines.push(bangla?(net>0?'আপনার কাছে পাওনা: '+amount:net<0?'আপনাকে দিতে হবে: '+amount:'আমাদের হিসাব সম্পূর্ণ পরিশোধিত।'):(net>0?'Amount due from you: '+amount:net<0?'Amount payable to you: '+amount:'Our account is settled.'));lines.push('— '+owner,'DailyTally');return lines.join('\n')}
function smsRecipient(phone){let value=String(phone||'').replace(/[০-৯]/g,d=>'০১২৩৪৫৬৭৮৯'.indexOf(d)).replace(/[\s().-]/g,'');if(/^01\d{9}$/.test(value))value='+88'+value;else if(/^8801\d{9}$/.test(value))value='+'+value;else if(/^00\d+$/.test(value))value='+'+value.slice(2);if(!/^\+?\d{7,15}$/.test(value))throw Error('SMS পাঠানোর জন্য ব্যক্তির সঠিক মোবাইল নম্বর দিন।');return value}
function sendStatementSMS(personId){if(typeof accountBusy!=='undefined'&&accountBusy)return;try{const person=db.people.find(p=>p.id===personId);if(!person)throw Error('ব্যক্তির তথ্য পাওয়া যায়নি।');const number=smsRecipient(person.phone),message=statementSMS(personId);if(typeof window.DailyTallyFiles?.openSms==='function'){window.DailyTallyFiles.openSms(number,message);return}const ios=/iPhone|iPad|iPod/.test(navigator.userAgent||'');window.location.href='sms:'+number+(ios?'&':'?')+'body='+encodeURIComponent(message)}catch(error){alert(featureText(error.message))}}
function addLedgerSMSButton(dialog,personId){const balance=dialog.querySelector('.ledger-balance-bar');if(!balance)return;const button=document.createElement('button');button.type='button';button.className='ledger-sms-button';button.innerHTML='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M21 11a8 8 0 0 1-8 8H5l-3 3V11a8 8 0 0 1 8-8h3a8 8 0 0 1 8 8Z"/><path d="M7 9h9M7 13h6"/></svg><span>SMS পাঠান</span>';button.onclick=()=>sendStatementSMS(personId);balance.after(button)}
